export default "<!doctype html>\r\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Site Tracker — Project visits & reports</title><meta name=\"description\" content=\"A clear view of every site. Manage project visits, track finishing works, and review inspection reports.\"><link href=\"https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\r\n<style>\r\n:root{--ink:#173337;--muted:#718084;--bg:#f4f5f0;--line:#e0e5dc;--orange:#e57943;--green:#477660;--cream:#f7ede0}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px 'DM Sans',sans-serif}button,input,select,textarea{font:inherit}button,a{touch-action:manipulation}button{cursor:pointer}a{color:inherit;text-decoration:none}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #df8c57;outline-offset:3px}.sidebar{width:224px;position:fixed;inset:0 auto 0 0;background:var(--ink);color:#c1d1ce;padding:32px 22px;display:flex;flex-direction:column}.brand{font:800 23px Manrope;color:#fff;display:flex;align-items:center;gap:10px;letter-spacing:-1px}.mark{width:31px;height:31px;border:2px solid #eca875;display:grid;place-items:center;color:#eca875;transform:rotate(-8deg);border-radius:8px}.brand small{font:10px 'DM Sans';letter-spacing:2px;display:block;color:#a0b8b2;margin-top:3px}.nav-label{font-size:10px;letter-spacing:1.8px;color:#8ea9a4;margin:48px 12px 14px}.nav{display:flex;flex-direction:column;gap:7px}.nav a{padding:13px 14px;border-radius:8px;display:flex;gap:12px;align-items:center;font-size:13px}.nav a.active{background:#2d4849;color:#fff}.nav a:hover{background:#294447}.nav i{font-style:normal;width:20px;font-size:18px}.side-foot{margin-top:auto;padding-top:30px;border-top:1px solid #3c5351;font-size:12px;line-height:1.8}.side-foot b{display:block;color:#f5e5cc}.online-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#9bc4a5;margin-right:6px}.shell{margin-left:224px;padding:0 42px 42px;max-width:1800px}.topbar{height:89px;display:flex;align-items:center;gap:18px;border-bottom:1px solid var(--line)}.breadcrumb{font-size:12px;color:var(--muted);flex:1}.breadcrumb b{color:var(--ink);font-weight:500}.date{font-size:12px;color:var(--muted)}.avatar{height:35px;width:35px;border-radius:50%;background:#e6e8df;display:grid;place-items:center;font-weight:700;font-size:11px}.headline{display:flex;align-items:end;justify-content:space-between;gap:20px;margin:34px 0 27px}.eyebrow{font-size:10px;font-weight:700;letter-spacing:2px;color:var(--muted);text-transform:uppercase}h1{font:800 31px Manrope;letter-spacing:-1.2px;margin:7px 0 9px}h2{font:800 18px Manrope;margin:0}p{color:var(--muted);line-height:1.7}.headline p{margin:0;font-size:13px}.actions{display:flex;gap:9px;flex-wrap:wrap}.btn{border:1px solid var(--line);background:#fff;padding:11px 16px;border-radius:7px;font-weight:600;font-size:12px;display:inline-flex;align-items:center;justify-content:center;gap:7px;color:var(--ink)}.btn.primary{background:var(--ink);color:#fff;border-color:var(--ink)}.btn.orange{background:var(--orange);border-color:var(--orange);color:#fff}.btn:hover{filter:brightness(.96)}.hero{background:var(--ink);border-radius:13px;min-height:171px;position:relative;overflow:hidden;display:flex;align-items:center;justify-content:space-between;padding:29px 32px;color:#fff}.hero h2{font-size:25px;letter-spacing:-.7px;max-width:430px;line-height:1.4}.hero p{color:#b7cbc4;font-size:12px;margin:10px 0 18px}.hero .eyebrow{color:#eab48b;margin-bottom:11px}.hero a{font-size:12px;color:#f3c5a5;font-weight:600}.structure{height:132px;width:252px;position:relative;margin-right:10px;opacity:.6;flex-shrink:0}.building{position:absolute;border:1px solid #bdc8b5;border-bottom:0;bottom:0;right:20px;width:125px;height:114px;background:repeating-linear-gradient(0deg,transparent 0 26px,#91a99d 27px 28px),repeating-linear-gradient(90deg,transparent 0 28px,#91a99d 29px 30px);transform:skewY(-9deg)}.building.back{height:80px;width:75px;right:145px;bottom:2px}.ground{position:absolute;bottom:0;width:252px;border-top:1px solid #bfcaaf}.crane{position:absolute;height:130px;border-left:2px solid #e2a06d;left:100px;bottom:0}.crane:before{content:'';position:absolute;width:145px;border-top:2px solid #e2a06d;left:-52px;top:10px;transform:rotate(-4deg)}.crane:after{content:'';position:absolute;height:50px;border-left:1px solid #e2a06d;left:76px;top:6px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin:22px 0 28px}.stat{border:1px solid var(--line);background:white;padding:20px 22px;border-radius:10px}.stat-top{display:flex;justify-content:space-between;color:var(--muted);font-size:11px}.stat-icon{color:var(--green);font-size:17px}.stat strong{font:800 30px Manrope;display:block;margin:10px 0 5px;letter-spacing:-1px}.stat small{color:var(--muted);font-size:10px}.stat small.accent{color:var(--green)}.section-row{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:19px}.section-row p{font-size:11px;margin:5px 0 0}.link{color:var(--green);font-weight:600;font-size:12px;background:none;border:0;padding:0}.project-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:17px;margin-bottom:30px}.project-card{background:#fff;border:1px solid var(--line);border-radius:10px;padding:20px;transition:transform .15s}.project-card:hover{transform:translateY(-2px)}.project-top{display:flex;align-items:center;justify-content:space-between;gap:8px}.project-icon{width:36px;height:36px;border-radius:8px;background:#f1eee5;display:grid;place-items:center;font-size:19px}.badge{display:inline-block;border-radius:5px;padding:5px 8px;font-size:10px;font-weight:600;background:#e9f0e8;color:#53755b;white-space:nowrap}.badge.amber{background:#fbf0dd;color:#a17a31}.badge.gray{background:#eef0ed;color:#70807a}.project-card h3{font:800 15px Manrope;margin:18px 0 6px}.project-card p{font-size:11px;margin:0}.progress-label{display:flex;justify-content:space-between;font-size:10px;margin:23px 0 8px;color:var(--muted)}.progress-label b{color:var(--ink)}.track{height:5px;background:#edf0e9;border-radius:3px;overflow:hidden}.fill{height:100%;background:var(--green);border-radius:3px}.card-foot{display:flex;justify-content:space-between;gap:8px;border-top:1px solid var(--line);padding-top:14px;margin-top:21px;font-size:10px;color:var(--muted)}.card-foot a{color:var(--ink);font-weight:700}.panel{border:1px solid var(--line);background:#fff;border-radius:11px;padding:23px;margin-bottom:26px}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;text-align:left;white-space:nowrap}th{font-size:10px;letter-spacing:.7px;color:var(--muted);text-transform:uppercase;font-weight:500;background:#f7f8f4;padding:12px 14px}td{padding:17px 14px;border-bottom:1px solid #eef0e9;font-size:12px}tr:last-child td{border-bottom:0}.subcell{display:block;font-size:10px;color:var(--muted);margin-top:5px}.empty{border:1px dashed #cfd8cc;border-radius:10px;padding:32px;text-align:center;grid-column:1/-1;background:#fafbf7}.empty h3{font:700 15px Manrope}.empty p{font-size:12px;margin-bottom:20px}.footer{display:flex;justify-content:space-between;font-size:10px;color:var(--muted);margin-top:20px}.toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:22px 0}.search{min-width:220px;flex:1}.toolbar input,.toolbar select{padding:11px 13px;border:1px solid var(--line);border-radius:7px;background:white;color:var(--ink)}.hidden{display:none!important}dialog{border:0;border-radius:14px;padding:0;max-width:650px;width:calc(100% - 32px);box-shadow:0 25px 100px #17333730;color:var(--ink)}dialog::backdrop{background:#0b2529a8;backdrop-filter:blur(3px)}.dialog-head{padding:24px 27px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center}.close{background:none;border:0;font-size:24px;color:var(--muted)}form{padding:24px 27px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}label{font-size:11px;font-weight:700;display:block}label input,label select,label textarea{width:100%;display:block;margin-top:7px;border:1px solid #d7ded3;border-radius:7px;padding:11px;color:var(--ink);background:#fff}label textarea{min-height:90px;resize:vertical}.wide{grid-column:1/-1}.form-foot{display:flex;justify-content:flex-end;gap:10px;margin-top:24px}.error{padding:14px 18px;background:#fbe9df;color:#914b30;border-radius:8px;margin:18px 0;font-size:12px}.notice{font-size:11px;background:#ecf0e8;padding:12px 14px;border-radius:7px;color:#61705f;line-height:1.7;margin-bottom:20px}.report-dialog{max-width:1000px}.report-dialog iframe{width:100%;height:70vh;border:0}.toast{position:fixed;bottom:25px;left:50%;transform:translateX(-50%);background:var(--ink);color:#fff;border-radius:8px;padding:12px 20px;z-index:10;font-size:12px;box-shadow:0 4px 24px #0003}.loading{color:var(--muted);padding:32px}.report-count{font-size:11px;color:var(--muted)}@media(min-width:1500px){.shell{padding-left:60px;padding-right:60px}}@media(max-width:1100px){.sidebar{width:190px;padding:27px 16px}.shell{margin-left:190px;padding:0 25px 30px}.project-grid{grid-template-columns:repeat(2,1fr)}.structure{width:210px;transform:scale(.85)}.stats{gap:10px}.stat{padding:16px}}@media(max-width:760px){.sidebar{position:static;width:100%;padding:18px 20px;gap:20px}.brand{font-size:20px}.brand small,.nav-label,.side-foot{display:none}.nav{flex-direction:row;gap:4px;overflow-x:auto}.nav a{padding:8px 11px;font-size:11px;white-space:nowrap}.nav i{font-size:15px;width:15px}.shell{margin-left:0;padding:0 19px 28px}.topbar{height:57px}.headline{align-items:start;flex-direction:column;margin:25px 0}.headline h1{font-size:28px}.stats{grid-template-columns:repeat(2,1fr);gap:10px}.hero{padding:24px}.hero h2{font-size:22px}.structure{display:none}.project-grid{grid-template-columns:1fr}.panel{padding:17px}.form-grid{grid-template-columns:1fr}.wide{grid-column:auto}.footer{gap:12px}.date{font-size:10px}.avatar{display:none}.section-row{align-items:start}.section-row .actions{justify-content:end}.toolbar{align-items:stretch}.search{min-width:150px}.hero p{max-width:260px}}\r\n\r\n</style><style>\r\n/* A focused home screen; detailed tools remain in their own views. */\r\n.home .sidebar{display:none}.home .shell{margin:0 auto;max-width:1120px;padding:0 40px 32px}.home .topbar{height:88px}.home .breadcrumb{display:none}.home-brand{display:none}.home .home-brand{display:flex;align-items:center;gap:10px;font:800 19px Manrope;letter-spacing:-.6px;flex:1}.home-brand .mark{height:29px;width:29px;font-size:20px}.home .avatar{display:none}.launch-heading{padding:70px 0 32px}.launch-heading h1{font-size:38px;letter-spacing:-1.5px;margin:10px 0 12px}.launch-heading p{margin:0;font-size:14px}.launch-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.launch-card{display:flex;flex-direction:column;align-items:flex-start;background:#fff;border:1px solid var(--line);border-radius:18px;padding:30px;min-height:255px;transition:transform .18s,box-shadow .18s,border-color .18s}.launch-card:hover{transform:translateY(-4px);border-color:#a8bcb0;box-shadow:0 14px 36px #1733370a}.launch-icon{display:grid;place-items:center;width:58px;height:58px;border-radius:16px;background:#edf3ed;color:var(--green);margin-bottom:26px}.launch-icon svg{width:28px;height:28px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}.launch-card:nth-child(2) .launch-icon{background:#fbefe5;color:#bd784b}.launch-card:nth-child(3) .launch-icon{background:#eef1f4;color:#627785}.launch-card h2{font-size:18px;letter-spacing:-.5px}.launch-card p{font-size:12px;margin:10px 0 25px;max-width:220px;line-height:1.7}.launch-open{margin-top:auto;display:flex;justify-content:space-between;width:100%;font-size:11px;color:var(--muted)}.launch-open span:last-child{color:var(--ink);font-size:18px}.launch-secondary{display:flex;justify-content:space-between;align-items:center;gap:20px;margin:30px 0 80px;font-size:12px;color:var(--muted)}.launch-secondary a{color:var(--green);padding:8px 0}.home .footer{padding-top:22px;border-top:1px solid var(--line)}\r\n@media(max-width:760px){.home .shell{padding:0 22px 24px}.home .topbar{height:74px}.home .date{font-size:10px;max-width:110px;text-align:right}.launch-heading{padding:40px 0 26px}.launch-heading h1{font-size:30px}.launch-grid{grid-template-columns:1fr;gap:14px}.launch-card{padding:24px;min-height:0;display:grid;grid-template-columns:48px 1fr;column-gap:18px;align-items:center}.launch-icon{width:48px;height:48px;border-radius:13px;margin:0;grid-row:1/4}.launch-card h2{font-size:17px}.launch-card p{margin:7px 0 12px;max-width:none}.launch-open{grid-column:2}.launch-secondary{margin:22px 0 40px;flex-wrap:wrap;gap:8px}.home .footer{font-size:9px}}\r\n@media(prefers-reduced-motion:reduce){.launch-card{transition:none}.launch-card:hover{transform:none}}\r\n</style></head><body>\r\n<aside class=\"sidebar\"><a class=\"brand\" href=\"/\"><span class=\"mark\">▥</span><span>site tracker<small>PROJECT INTELLIGENCE</small></span></a><div class=\"nav-label\">WORKSPACE</div><nav class=\"nav\" aria-label=\"Main navigation\"><a href=\"#dashboard\" data-nav=\"dashboard\" class=\"active\"><i>▦</i>Overview</a><a href=\"#projects\" data-nav=\"projects\"><i>▤</i>Projects</a><a href=\"#visits\" data-nav=\"visits\"><i>◎</i>Site visits</a><a href=\"#reports\" data-nav=\"reports\"><i>▧</i>Weekly Project Reports</a><a href=\"/5s\"><i>◎</i>Site 5S & Appearance</a><a href=\"/workspace\"><i>☷</i>Field workspace ↗</a></nav><div class=\"side-foot\"><b>Built for the field.</b>Clarity for every decision.<br><br><span class=\"online-dot\"></span><span id=\"syncState\">Connecting to online storage</span></div></aside>\r\n<div class=\"shell\"><header class=\"topbar\"><a class=\"home-brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">▥</span>site tracker</a><div class=\"breadcrumb\">Workspace <span style=\"padding:0 10px\">/</span> <b id=\"crumb\">Overview</b></div><span class=\"date\" id=\"today\"></span><div class=\"avatar\">ST</div></header><div id=\"error\" class=\"error hidden\" role=\"alert\"></div><main id=\"app\"><div class=\"loading\">Loading your projects and reports…</div></main><footer class=\"footer\"><span>SITE TRACKER · Project visits & reporting</span><a href=\"/workspace\">Field workspace ↗</a></footer></div>\r\n<dialog id=\"visitDialog\"><div class=\"dialog-head\"><h2 id=\"visitTitle\">Record a site visit</h2><button class=\"close\" data-close aria-label=\"Close\">×</button></div><form id=\"visitForm\"><div class=\"form-grid\"><label class=\"wide\">Project / space<select name=\"spaceId\" id=\"visitProject\" required></select></label><label>Visit date<input name=\"date\" type=\"date\" required></label><label>Inspector<input name=\"inspector\" maxlength=\"150\" placeholder=\"Full name\" required></label><label>Visit type<select name=\"type\"><option>Progress inspection</option><option>Quality inspection</option><option>Snagging</option><option>Handover</option><option>Follow-up</option></select></label><label>Outcome<select name=\"outcome\"><option>On track</option><option>Action required</option><option>Completed</option></select></label><label class=\"wide\">Observations<textarea name=\"observations\" placeholder=\"What did you observe on site?\" maxlength=\"12000\" required></textarea></label><label class=\"wide\">Next actions<textarea name=\"actions\" placeholder=\"Required actions, responsible parties and target dates\" maxlength=\"12000\"></textarea></label><label>Next visit<input name=\"nextDate\" type=\"date\"></label><label>Weather / conditions<input name=\"weather\" placeholder=\"e.g. Clear, 30°C\" maxlength=\"150\"></label></div><div id=\"visitError\" class=\"error hidden\" role=\"alert\"></div><div class=\"form-foot\"><button type=\"button\" class=\"btn\" data-close>Cancel</button><button class=\"btn primary\" type=\"submit\">Save visit</button></div></form></dialog>\r\n<dialog id=\"projectDialog\"><div class=\"dialog-head\"><h2>Create a project</h2><button class=\"close\" data-close aria-label=\"Close\">×</button></div><form id=\"projectForm\"><label>Project / space name<input name=\"name\" maxlength=\"200\" placeholder=\"e.g. J1 — Level 02\" required></label><p style=\"font-size:12px\">Create a space, then add tasks and photos in the field workspace. You can also use “Add new space” in the workspace to start with the full finishing checklist.</p><div id=\"projectError\" class=\"error hidden\" role=\"alert\"></div><div class=\"form-foot\"><button type=\"button\" class=\"btn\" data-close>Cancel</button><button class=\"btn primary\">Create project</button></div></form></dialog>\r\n<dialog id=\"reportDialog\" class=\"report-dialog\"><div class=\"dialog-head\"><h2 id=\"reportTitle\">Report preview</h2><div class=\"actions\"><button class=\"btn\" id=\"downloadReport\">Download HTML</button><button class=\"close\" data-close aria-label=\"Close\">×</button></div></div><iframe id=\"reportFrame\" title=\"Report preview\" sandbox=\"\"></iframe></dialog>\r\n<div id=\"toast\" class=\"toast hidden\" role=\"status\"></div>\r\n<script>\r\n'use strict';\r\nlet spaces=[],tasks=[],visits=[],reports=[],page='dashboard',search='',selectedProject='',editingVisit=null,reportHtml='',reportName='report';\r\nconst $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c])),uid=()=>crypto.randomUUID(),today=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')},date=v=>v?new Date(v.slice(0,10)+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'—';\r\n$('#today').textContent=new Date().toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'long',year:'numeric'});\r\nasync function api(store,method='GET',value=null,id=null){const q=new URLSearchParams({store});if(id)q.set('id',id);const res=await fetch('/api/data?'+q,{method,headers:{'Content-Type':'application/json'},...(value?{body:JSON.stringify(value)}:{})});const data=await res.json();if(!res.ok)throw new Error(data.error||'Please try again.');return data;}\r\nfunction toast(text){$('#toast').textContent=text;$('#toast').classList.remove('hidden');setTimeout(()=>$('#toast').classList.add('hidden'),3200)}\r\nasync function load(){try{[spaces,tasks,visits,reports]=await Promise.all(['spaces','tasks','visits','reportHistory'].map(s=>api(s)));$('#error').classList.add('hidden');$('#syncState').textContent='Online · Changes saved to cloud';render()}catch(e){$('#error').textContent=e.message+' Reload the page to reconnect.';$('#error').classList.remove('hidden');$('#syncState').textContent='Connection unavailable';$('#app').innerHTML='<div class=\"empty\"><h3>Unable to load your workspace</h3><p>Your saved information will appear when the connection is restored.</p><button class=\"btn primary\" onclick=\"load()\">Try again</button></div>'}}\r\nfunction project(id){return spaces.find(x=>x.id===id)?.name||'Removed project'}\r\nfunction progress(id){const list=tasks.filter(t=>t.spaceId===id),done=list.filter(t=>t.status==='done').length;return{total:list.length,done,pct:list.length?Math.round(done/list.length*100):0}}\r\nfunction badge(value){return '<span class=\"badge '+(value==='Action required'?'amber':value==='Not started'?'gray':'')+'\">'+esc(value)+'</span>'}\r\nfunction heading(title,sub,buttons=true){return '<div class=\"headline\"><div><div class=\"eyebrow\">Project intelligence</div><h1>'+title+'</h1><p>'+sub+'</p></div>'+(buttons?'<div class=\"actions\"><button class=\"btn\" onclick=\"newProject()\">＋ New project</button><button class=\"btn primary\" onclick=\"newVisit()\">＋ Record visit</button></div>':'')+'</div>'}\r\nfunction stats(){const done=tasks.filter(t=>t.status==='done').length,pct=tasks.length?Math.round(done/tasks.length*100):0;return '<div class=\"stats\">'+[['Projects & spaces',spaces.length,'Across your workspace','▤'],['Site visits',visits.length,'Recorded inspections','◎'],['Overall completion',pct+'%',done+' of '+tasks.length+' tasks completed','↗'],['Action required',visits.filter(v=>v.outcome==='Action required').length,'Visits needing follow-up','⚑']].map(x=>'<div class=\"stat\"><div class=\"stat-top\">'+x[0]+'<span class=\"stat-icon\">'+x[3]+'</span></div><strong>'+x[1]+'</strong><small>'+x[2]+'</small></div>').join('')+'</div>'}\r\nfunction projectCards(list){return '<div class=\"project-grid\">'+(list.length?list.map(s=>{const p=progress(s.id),sv=visits.filter(v=>v.spaceId===s.id).sort((a,b)=>b.date.localeCompare(a.date)),state=sv[0]?.outcome||(p.total?(p.pct===100?'Completed':'In progress'):'Not started');return '<article class=\"project-card\"><div class=\"project-top\"><span class=\"project-icon\">▥</span>'+badge(state)+'</div><h3>'+esc(s.name)+'</h3><p>'+p.total+' tracked tasks · '+sv.length+' site visits</p><div class=\"progress-label\"><span>Finishing progress</span><b>'+p.pct+'%</b></div><div class=\"track\"><div class=\"fill\" style=\"width:'+p.pct+'%\"></div></div><div class=\"card-foot\"><span>'+(sv[0]?'Last visit '+date(sv[0].date):'No visits recorded')+'</span><a href=\"/workspace?space='+encodeURIComponent(s.id)+'\">Open workspace ↗</a></div></article>'}).join(''):'<div class=\"empty\"><h3>Your first project starts here</h3><p>Create a project or restore your existing backup in the field workspace.</p><button class=\"btn primary\" onclick=\"newProject()\">＋ Create project</button> <a class=\"btn\" href=\"/workspace\">Open workspace ↗</a></div>')+'</div>'}\r\nfunction visitsTable(list,full=false){return list.length?'<div class=\"table-wrap\"><table><thead><tr><th>Project / inspector</th><th>Visit date</th><th>Inspection</th><th>Outcome</th><th>Report</th>'+(full?'<th>Manage</th>':'')+'</tr></thead><tbody>'+list.map(v=>'<tr><td><b>'+esc(project(v.spaceId))+'</b><span class=\"subcell\">'+esc(v.inspector)+'</span></td><td>'+date(v.date)+'</td><td>'+esc(v.type)+'</td><td>'+badge(v.outcome)+'</td><td><button class=\"link\" data-visit-report=\"'+esc(v.id)+'\">View report ↗</button></td>'+(full?'<td><button class=\"link\" data-edit-visit=\"'+esc(v.id)+'\">Edit</button></td>':'')+'</tr>').join('')+'</tbody></table></div>':'<div class=\"empty\"><h3>No visits recorded yet</h3><p>Capture observations, next actions and inspection outcomes in one place.</p><button class=\"btn primary\" onclick=\"newVisit()\">＋ Record a visit</button></div>'}\r\nfunction sortedVisits(){return [...visits].sort((a,b)=>b.date.localeCompare(a.date)||(b.createdAt||0)-(a.createdAt||0))}\r\nfunction filters(){return '<div class=\"toolbar\"><input class=\"search\" type=\"search\" id=\"search\" aria-label=\"Search\" placeholder=\"Search '+(page==='projects'?'projects':'reports, inspectors or projects')+'…\" value=\"'+esc(search)+'\">'+(page!=='projects'?'<select id=\"projectFilter\" aria-label=\"Filter by project\"><option value=\"\">All projects</option>'+spaces.map(s=>'<option value=\"'+esc(s.id)+'\" '+(s.id===selectedProject?'selected':'')+'>'+esc(s.name)+'</option>').join('')+'</select>':'')+'</div>'}\r\nfunction match(item){return (!selectedProject||item.spaceId===selectedProject)&&(!search||[project(item.spaceId),item.inspector,item.observations,item.type].join(' ').toLowerCase().includes(search.toLowerCase()))}\r\nfunction render(){page=location.hash.slice(1)||'dashboard';if(!['dashboard','projects','visits','reports'].includes(page))page='dashboard';document.body.classList.toggle('home',page==='dashboard');document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===page));$('#crumb').textContent={dashboard:'Overview',projects:'Projects',visits:'Site visits',reports:'Report library'}[page];let html='';if(page==='dashboard'){html='<section class=\"launch-heading\"><div class=\"eyebrow\">YOUR SITE WORKSPACE</div><h1>What would you like to do?</h1><p>Reports, inspections and projects. Everything starts here.</p></section><nav class=\"launch-grid\" aria-label=\"Main tools\">'+[\r\n ['#reports','<path d=\"M8 3h8l4 4v17H4V3h4Z\"/><path d=\"M15 3v6h5M8 14h8M8 18h5\"/>','Weekly reports','Review saved reports and keep your weekly updates together.','Open reports'],\r\n ['/5s','<path d=\"M12 3 22 7v6c0 6-10 11-10 11S2 19 2 13V7l10-4Z\"/><path d=\"m7 13 3 3 7-7\"/>','Site 5S & Appearance','Inspect your site, review scores and follow up on actions.','Open 5S'],\r\n ['#projects','<rect x=\"4\" y=\"3\" width=\"16\" height=\"21\" rx=\"2\"/><path d=\"M8 8h2m4 0h2M8 12h2m4 0h2M8 16h2m4 0h2M10 24v-4h4v4\"/>','Projects','Find a project and continue tracking work on site.','View projects']\r\n ].map(([href,icon,title,description,label])=>'<a class=\"launch-card\" href=\"'+href+'\"><span class=\"launch-icon\"><svg viewBox=\"0 0 26 28\" aria-hidden=\"true\">'+icon+'</svg></span><h2>'+title+'</h2><p>'+description+'</p><span class=\"launch-open\"><span>'+label+'</span><span aria-hidden=\"true\">↗</span></span></a>').join('')+'</nav><div class=\"launch-secondary\"><span>'+spaces.length+' projects in your workspace</span><a href=\"#visits\">Site visit log →</a></div>';}else if(page==='projects'){html=heading('Projects & spaces','Track work across every site, floor, unit and room.')+filters()+'<div id=\"results\">'+projectCards(spaces.filter(s=>s.name.toLowerCase().includes(search.toLowerCase())))+'</div>';}else if(page==='visits'){html=heading('Site visit log','A structured record of every inspection and follow-up.')+filters()+'<section class=\"panel\" id=\"results\">'+visitsTable(sortedVisits().filter(match),true)+'</section>';}else{html=heading('Report library','Review visit reports and saved finishing reports.',false)+filters()+'<div class=\"notice\">Visit reports reflect saved visit observations. Checklist, detailed status and timeline reports are created in the field workspace and saved as snapshots.</div><section class=\"panel\" id=\"results\">'+reportRows()+'</section>';}$('#app').innerHTML=html;wire();}\r\nfunction reportRows(){const list=[...visits.map(v=>({id:v.id,spaceId:v.spaceId,type:v.type,title:'Site visit report',date:v.date,isVisit:true,inspector:v.inspector,observations:v.observations})),...reports.map(r=>({...r,title:r.type==='timeline'?'Timeline report':r.type==='status'?'Detailed status report':'Checklist report',date:r.reportDate||new Date(r.createdAt||Date.now()).toISOString().slice(0,10)}))].filter(match).sort((a,b)=>(b.date||'').localeCompare(a.date||''));return list.length?'<div class=\"section-row\"><h2>Saved reports</h2><span class=\"report-count\">'+list.length+' reports</span></div><div class=\"table-wrap\"><table><thead><tr><th>Report</th><th>Project / space</th><th>Date</th><th>Open</th></tr></thead><tbody>'+list.map(r=>'<tr><td><b>'+esc(r.title)+'</b><span class=\"subcell\">'+esc(r.isVisit?r.inspector:'Saved snapshot')+'</span></td><td>'+esc(project(r.spaceId))+'</td><td>'+date(r.date)+'</td><td><button class=\"link\" '+(r.isVisit?'data-visit-report':'data-snapshot')+'=\"'+esc(r.id)+'\">View report ↗</button></td></tr>').join('')+'</tbody></table></div>':'<div class=\"empty\"><h3>No matching reports</h3><p>Record a site visit, or generate a report from the field workspace.</p><a class=\"btn primary\" href=\"/workspace\">Open field workspace ↗</a></div>'}\r\nfunction wire(){if($('#search'))$('#search').oninput=e=>{search=e.target.value;updateResults()};if($('#projectFilter'))$('#projectFilter').onchange=e=>{selectedProject=e.target.value;updateResults()};wireRows()}\r\nfunction updateResults(){$('#results').innerHTML=page==='projects'?projectCards(spaces.filter(s=>s.name.toLowerCase().includes(search.toLowerCase()))):page==='visits'?visitsTable(sortedVisits().filter(match),true):reportRows();wireRows()}\r\nfunction wireRows(){document.querySelectorAll('[data-visit-report]').forEach(b=>b.onclick=()=>showVisitReport(b.dataset.visitReport));document.querySelectorAll('[data-edit-visit]').forEach(b=>b.onclick=()=>newVisit(b.dataset.editVisit));document.querySelectorAll('[data-snapshot]').forEach(b=>b.onclick=()=>{const r=reports.find(x=>x.id===b.dataset.snapshot);openReport(r.html||r.content||'<p>Report content is unavailable.</p>',project(r.spaceId)+' report')})}\r\nfunction newProject(){$('#projectForm').reset();$('#projectError').classList.add('hidden');$('#projectDialog').showModal()}\r\nfunction newVisit(id=null){if(!spaces.length){newProject();toast('Create your first project to record a visit.');return}editingVisit=id;const form=$('#visitForm');form.reset();$('#visitError').classList.add('hidden');$('#visitTitle').textContent=id?'Edit site visit':'Record a site visit';$('#visitProject').innerHTML=spaces.map(s=>'<option value=\"'+esc(s.id)+'\">'+esc(s.name)+'</option>').join('');form.elements.date.value=today();if(id){const v=visits.find(x=>x.id===id);Object.keys(v).forEach(k=>{if(form.elements[k])form.elements[k].value=v[k]||''})}$('#visitDialog').showModal()}\r\ndocument.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());\r\n$('#projectForm').onsubmit=async e=>{e.preventDefault();const btn=e.target.querySelector('[type=submit]')||e.target.querySelector('.primary');btn.disabled=true;try{const name=new FormData(e.target).get('name').trim();if(!name)throw new Error('Enter a project name.');await api('spaces','PUT',{id:uid(),name,createdAt:Date.now(),reportDate:today(),order:Date.now()});$('#projectDialog').close();await load();toast('Project created. Add tasks in the field workspace.')}catch(err){$('#projectError').textContent=err.message;$('#projectError').classList.remove('hidden')}finally{btn.disabled=false}};\r\n$('#visitForm').onsubmit=async e=>{e.preventDefault();const btn=e.target.querySelector('[type=submit]');btn.disabled=true;try{const old=visits.find(x=>x.id===editingVisit);const v={...Object.fromEntries(new FormData(e.target)),id:editingVisit||uid(),createdAt:old?.createdAt||Date.now(),updatedAt:Date.now()};v.inspector=v.inspector.trim();v.observations=v.observations.trim();if(!v.inspector||!v.observations)throw new Error('Inspector and observations are required.');if(v.nextDate&&v.nextDate<v.date)throw new Error('The next visit must be on or after this visit.');await api('visits','PUT',v);$('#visitDialog').close();await load();toast('Visit saved. Your report is ready in the report library.')}catch(err){$('#visitError').textContent=err.message;$('#visitError').classList.remove('hidden')}finally{btn.disabled=false}};\r\nfunction showVisitReport(id){const v=visits.find(x=>x.id===id);if(!v)return;const html='<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Site visit report</title><style>body{font:14px Arial;color:#173337;max-width:850px;margin:40px auto;padding:25px;line-height:1.8}h1{font-size:32px}header{border-top:6px solid #173337;border-bottom:1px solid #ddd;padding:20px 0}small{letter-spacing:2px;color:#718084}dl{display:grid;grid-template-columns:140px 1fr;gap:10px;margin:28px 0}dt{color:#718084}dd{margin:0}h2{font-size:17px;margin-top:30px}p{white-space:pre-wrap}.outcome{background:#f0f3eb;padding:12px 20px}footer{border-top:1px solid #ddd;padding-top:16px;margin-top:40px;color:#718084;font-size:11px}</style></head><body><header><small>SITE TRACKER / FIELD REPORT</small><h1>Site visit report</h1><div>'+esc(project(v.spaceId))+'</div></header><dl><dt>Visit date</dt><dd>'+date(v.date)+'</dd><dt>Inspector</dt><dd>'+esc(v.inspector)+'</dd><dt>Inspection type</dt><dd>'+esc(v.type)+'</dd><dt>Conditions</dt><dd>'+esc(v.weather||'Not recorded')+'</dd></dl><div class=\"outcome\">Outcome: <b>'+esc(v.outcome)+'</b></div><h2>Site observations</h2><p>'+esc(v.observations)+'</p><h2>Next actions</h2><p>'+esc(v.actions||'No next actions recorded.')+'</p><h2>Next visit</h2><p>'+date(v.nextDate)+'</p><footer>Site Tracker · Generated from saved visit information</footer></body></html>';openReport(html,project(v.spaceId)+' — '+v.date)}\r\nconst snapshotStyles = \"\\r\\n  :root{\\r\\n    --bg: #eae6dc;\\r\\n    --panel: #f6f3ea;\\r\\n    --ink: #211d18;\\r\\n    --ink-soft: #6b6357;\\r\\n    --line: #cfc6b2;\\r\\n    --accent: #d9541c;\\r\\n    --amber: #e2a100;\\r\\n    --green: #4c7a3d;\\r\\n    --stone: #9a9080;\\r\\n    --danger: #b23a2e;\\r\\n    --radius: 3px;\\r\\n  }\\r\\n  *{ box-sizing:border-box; }\\r\\n  html,body{ margin:0; padding:0; }\\r\\n  body{\\r\\n    background:var(--bg); color:var(--ink);\\r\\n    font-family:'Archivo', Arial, sans-serif; font-size:15px; line-height:1.6;\\r\\n    -webkit-tap-highlight-color: transparent;\\r\\n  }\\r\\n  ::selection{ background: var(--accent); color:#fff; }\\r\\n  button{ font-family:inherit; }\\r\\n\\r\\n  /* ---- Header ---- */\\r\\n  header.top{\\r\\n    background: var(--ink); color:#f2ede0; padding: 16px 16px 14px;\\r\\n    position: sticky; top:0; z-index:20; border-bottom: 4px solid var(--accent);\\r\\n  }\\r\\n  .top-row{ display:flex; align-items:center; justify-content:space-between; gap:10px; }\\r\\n  .top-left{ display:flex; align-items:center; gap:10px; min-width:0; }\\r\\n  .back-btn{\\r\\n    border:1px solid #4a453a; background:transparent; color:#f2ede0; border-radius:var(--radius);\\r\\n    padding:7px 10px; font-size:13px; cursor:pointer; flex:0 0 auto;\\r\\n  }\\r\\n  header.top h1{ font-size:17px; font-weight:800; margin:0; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }\\r\\n  header.top .sub{ font-size:12px; color:#c9c0ac; margin:2px 0 0; }\\r\\n  .progress-wrap{ min-width:100px; text-align:right; flex:0 0 auto; }\\r\\n  .progress-num{ font-size:20px; font-weight:900; color:#fff; line-height:1; }\\r\\n  .progress-label{ font-size:10.5px; color:#c9c0ac; margin-top:2px;}\\r\\n  .bar-track{ margin-top:10px; height:7px; background:#3a352c; border-radius:99px; overflow:hidden; }\\r\\n  .bar-fill{ height:100%; background: var(--accent); width:0%; transition: width .35s ease; }\\r\\n\\r\\n  .toolbar{\\r\\n    display:flex; gap:6px; margin-top:10px; flex-wrap:wrap;\\r\\n  }\\r\\n  .tool-btn{\\r\\n    border:1px solid #4a453a; background:#2b271f; color:#f2ede0; font-size:12px; font-weight:600;\\r\\n    padding:7px 11px; border-radius:var(--radius); cursor:pointer;\\r\\n  }\\r\\n  .tool-btn:hover{ border-color: var(--accent); }\\r\\n\\r\\n  /* ---- Filters ---- */\\r\\n  .filters{\\r\\n    position:sticky; top:0; z-index:19; background: var(--bg);\\r\\n    display:flex; flex-direction:column; gap:8px; padding:10px 16px; border-bottom:1px solid var(--line);\\r\\n  }\\r\\n  .search-row{ position:relative; }\\r\\n  .search-input{\\r\\n    width:100%; border:1px solid var(--line); border-radius:var(--radius); padding:8px 32px 8px 12px;\\r\\n    font-family:inherit; font-size:13.5px; background:var(--panel); color:var(--ink); box-sizing:border-box;\\r\\n  }\\r\\n  .search-input:focus{ outline:none; border-color:var(--accent); }\\r\\n  .search-clear{\\r\\n    position:absolute; inset-inline-end:6px; top:50%; transform:translateY(-50%);\\r\\n    border:none; background:none; color:var(--ink-soft); font-size:16px; line-height:1; cursor:pointer; padding:4px; display:none;\\r\\n  }\\r\\n  .chip-row{ display:flex; gap:6px; overflow-x:auto; }\\r\\n  .chip-row::-webkit-scrollbar{ display:none; }\\r\\n  .chip{\\r\\n    flex:0 0 auto; padding:7px 14px; border:1px solid var(--line); background:var(--panel);\\r\\n    color:var(--ink-soft); font-size:12.5px; font-weight:600; border-radius:99px; cursor:pointer; white-space:nowrap;\\r\\n  }\\r\\n  .chip.active{ background: var(--ink); border-color:var(--ink); color:#fff; }\\r\\n\\r\\n  main{ padding: 14px 14px 100px; max-width:760px; margin:0 auto; }\\r\\n\\r\\n  /* ---- Home / space list ---- */\\r\\n  .home-sort{\\r\\n    position:sticky; top:0; z-index:19; background: var(--bg);\\r\\n    display:flex; align-items:center; gap:10px; padding:10px 16px; border-bottom:1px solid var(--line); flex-wrap:wrap;\\r\\n  }\\r\\n  .home-sort-label{ font-size:12px; color:var(--ink-soft); font-weight:600; flex:0 0 auto; }\\r\\n  .home-sort-hint{ font-size:11.5px; color:var(--ink-soft); font-style:italic; flex:0 0 auto; }\\r\\n  .space-card{\\r\\n    background:var(--panel); border:1px solid var(--line); border-inline-start:5px solid var(--accent);\\r\\n    border-radius:var(--radius); padding:14px 16px; margin-bottom:10px; cursor:pointer;\\r\\n    display:flex; align-items:center; gap:10px;\\r\\n  }\\r\\n  .space-card.dragging{ opacity:0.85; box-shadow:0 6px 16px rgba(0,0,0,0.18); }\\r\\n  .space-card .drag-handle{\\r\\n    flex:0 0 auto; color:var(--ink-soft); font-size:20px; line-height:1; letter-spacing:-2px;\\r\\n    padding:10px 6px; margin:-10px -6px; cursor:grab; touch-action:none; user-select:none;\\r\\n  }\\r\\n  .space-card .drag-handle:active{ cursor:grabbing; }\\r\\n  .space-card.selected{ background:#fbe9e0; border-inline-start-color:var(--danger); }\\r\\n  .select-circle{\\r\\n    flex:0 0 auto; width:22px; height:22px; border-radius:50%; border:2px solid var(--line);\\r\\n    display:flex; align-items:center; justify-content:center; font-size:13px; font-weight:900; color:#fff; background:#fff;\\r\\n  }\\r\\n  .select-circle.checked{ background:var(--danger); border-color:var(--danger); }\\r\\n  .space-card .space-card-body{ flex:1; min-width:0; }\\r\\n  .space-card h3{ margin:0 0 4px; font-size:16px; }\\r\\n  .space-card .meta{ font-size:12px; color:var(--ink-soft); display:flex; justify-content:space-between; gap:10px; }\\r\\n  .space-card .mini-bar{ height:5px; background:var(--line); border-radius:99px; margin-top:8px; overflow:hidden;}\\r\\n  .space-card .mini-fill{ height:100%; background:var(--green); }\\r\\n\\r\\n  .cat-heading{\\r\\n    font-size:13px; font-weight:700; color:var(--ink-soft); margin: 22px 4px 8px; padding-bottom:6px;\\r\\n    border-bottom:2px solid var(--line); display:flex; justify-content:space-between; align-items:center;\\r\\n  }\\r\\n  .cat-heading:first-child{ margin-top:4px; }\\r\\n  .cat-count{ font-weight:500; color:var(--stone); }\\r\\n\\r\\n  .card{\\r\\n    background:var(--panel); border:1px solid var(--line); border-inline-start: 5px solid var(--stone);\\r\\n    border-radius: var(--radius); padding: 12px 14px; margin-bottom:10px;\\r\\n  }\\r\\n  .card.status-inprogress{ border-inline-start-color: var(--amber); }\\r\\n  .card.status-done{ border-inline-start-color: var(--green); }\\r\\n\\r\\n  .card-head{ display:flex; justify-content:space-between; align-items:flex-start; gap:8px; }\\r\\n  .task-title{\\r\\n    font-weight:700; font-size:15px; flex:1; background:transparent; border:none; color:var(--ink);\\r\\n    font-family:inherit; resize:none; width:100%; padding:0; outline:none;\\r\\n  }\\r\\n  .del-btn{ border:none; background:transparent; color:var(--stone); font-size:16px; cursor:pointer; padding:2px 4px; line-height:1; }\\r\\n  .del-btn:hover{ color:var(--danger); }\\r\\n\\r\\n  .field-label{ font-size:11px; color:var(--ink-soft); margin: 8px 0 3px; display:block; }\\r\\n  .prereq-input, .notes-input, .cat-select{\\r\\n    width:100%; border:1px solid var(--line); background:#fff; border-radius:var(--radius);\\r\\n    padding:7px 9px; font-family:inherit; font-size:13px; color:var(--ink); outline:none;\\r\\n  }\\r\\n  .prereq-input, .cat-select{ resize:none; }\\r\\n  .notes-input{ resize:vertical; min-height:44px; }\\r\\n  .prereq-input:focus, .notes-input:focus, .task-title:focus, .cat-select:focus{ border-color: var(--accent); }\\r\\n\\r\\n  .dep-chips{ display:flex; flex-wrap:wrap; gap:6px; align-items:center; }\\r\\n  .dep-chip{\\r\\n    display:inline-flex; align-items:center; gap:6px; background:#fff; border:1px solid var(--line); border-radius:99px;\\r\\n    padding:5px 6px 5px 11px; font-size:12px; color:var(--ink);\\r\\n  }\\r\\n  .dep-chip .dep-remove{ border:none; background:var(--line); color:var(--ink); border-radius:50%; width:16px; height:16px; font-size:11px; line-height:1; cursor:pointer; padding:0; }\\r\\n  .dep-add-btn{\\r\\n    border:1px dashed var(--line); background:#fff; color:var(--ink-soft); font-size:12px; padding:6px 11px;\\r\\n    border-radius:99px; cursor:pointer;\\r\\n  }\\r\\n  .dep-add-btn:hover{ border-color:var(--accent); color:var(--accent); }\\r\\n  .dep-picker-modal{ max-width:420px; }\\r\\n  .dep-picker-list{ max-height:320px; overflow-y:auto; margin:12px 0; border:1px solid var(--line); border-radius:var(--radius); }\\r\\n  .dep-picker-item{ display:flex; align-items:center; gap:9px; padding:9px 10px; border-bottom:1px solid #eee; font-size:13.5px; cursor:pointer; }\\r\\n  .dep-picker-item:last-child{ border-bottom:none; }\\r\\n  .dep-picker-cat{ font-size:11.5px; color:var(--ink-soft); }\\r\\n\\r\\n  .status-row{ display:flex; gap:8px; margin-top:10px; flex-wrap:wrap; }\\r\\n  .status-btn{\\r\\n    flex:1; min-width:90px; padding:8px 6px; text-align:center; font-size:12px; font-weight:700;\\r\\n    border:1px solid var(--line); background:#fff; color:var(--ink-soft); cursor:pointer; border-radius: var(--radius);\\r\\n  }\\r\\n  .status-btn[data-s=\\\"notstarted\\\"].sel{ background: var(--stone); color:#fff; border-color:var(--stone); }\\r\\n  .status-btn[data-s=\\\"inprogress\\\"].sel{ background: var(--amber); color:#231c04; border-color:var(--amber); }\\r\\n  .status-btn[data-s=\\\"done\\\"].sel{ background: var(--green); color:#fff; border-color:var(--green); }\\r\\n\\r\\n  .date-row{ display:flex; gap:8px; margin-top:10px; }\\r\\n  .date-field{ flex:1; }\\r\\n  .date-field input{\\r\\n    width:100%; border:1px solid var(--line); background:#fff; border-radius:var(--radius);\\r\\n    padding:6px 8px; font-family:inherit; font-size:12.5px; color:var(--ink);\\r\\n  }\\r\\n\\r\\n  .photo-row{ margin-top:10px; display:flex; align-items:center; gap:10px; flex-wrap:wrap; }\\r\\n  .photo-thumb-wrap{ position:relative; display:inline-block; }\\r\\n  .photo-thumb{ width:64px; height:64px; object-fit:cover; border-radius:var(--radius); border:1px solid var(--line); cursor:pointer; display:block; }\\r\\n  .photo-remove-btn{\\r\\n    position:absolute; top:-7px; right:-7px; width:20px; height:20px; border-radius:50%;\\r\\n    background:var(--danger); color:#fff; border:2px solid var(--panel); font-size:13px; line-height:1;\\r\\n    cursor:pointer; display:flex; align-items:center; justify-content:center; padding:0;\\r\\n  }\\r\\n  .photo-remove-btn:hover{ opacity:0.85; }\\r\\n  .photo-btn{\\r\\n    display:inline-flex; align-items:center; gap:6px; border:1px dashed var(--line); background:#fff;\\r\\n    color:var(--ink-soft); font-size:12px; padding:8px 12px; border-radius:var(--radius); cursor:pointer;\\r\\n  }\\r\\n  .photo-btn:hover{ border-color: var(--accent); color:var(--accent); }\\r\\n  input[type=file]{ display:none; }\\r\\n\\r\\n  .add-bar{ position:fixed; bottom:0; right:0; left:0; padding:12px 16px; background:linear-gradient(to top, var(--bg) 60%, transparent); }\\r\\n  .add-btn{\\r\\n    max-width:760px; margin:0 auto; display:block; width:100%; background: var(--accent); color:#fff; border:none;\\r\\n    padding:13px; font-size:14.5px; font-weight:800; border-radius: var(--radius); cursor:pointer;\\r\\n  }\\r\\n  .add-btn:active{ opacity:0.85; }\\r\\n  .add-btn.secondary{ background:var(--ink); }\\r\\n  .add-btn.danger{ background:var(--danger); }\\r\\n  .add-btn:disabled{ opacity:0.4; cursor:default; }\\r\\n\\r\\n  .empty{ text-align:center; color:var(--ink-soft); padding:40px 20px; font-size:13.5px; }\\r\\n\\r\\n  .toast{\\r\\n    position:fixed; bottom:74px; left:50%; transform:translateX(-50%); background: var(--ink); color:#fff;\\r\\n    padding:9px 18px; border-radius:99px; font-size:12.5px; opacity:0; pointer-events:none; transition:opacity .25s ease; z-index:40;\\r\\n  }\\r\\n  .toast.show{ opacity:1; }\\r\\n\\r\\n  .lightbox{ position:fixed; inset:0; background:rgba(20,17,12,0.9); display:none; align-items:center; justify-content:center; z-index:50; padding:20px; }\\r\\n  .lightbox.open{ display:flex; }\\r\\n  .lightbox img{ max-width:100%; max-height:85vh; border-radius:4px; }\\r\\n  .lightbox .close{ position:absolute; top:16px; left:16px; color:#fff; font-size:26px; background:none; border:none; cursor:pointer;}\\r\\n\\r\\n  .modal-overlay{ position:fixed; inset:0; background:rgba(20,17,12,0.55); display:none; align-items:center; justify-content:center; z-index:60; padding:20px; }\\r\\n  .modal-overlay.open{ display:flex; }\\r\\n  .modal{ background:var(--panel); border-radius:6px; padding:20px; max-width:380px; width:100%; }\\r\\n  .modal h3{ margin:0 0 12px; font-size:16px; }\\r\\n  .modal input{ width:100%; border:1px solid var(--line); border-radius:var(--radius); padding:9px 10px; font-family:inherit; font-size:14px; }\\r\\n  .modal-actions{ display:flex; gap:8px; margin-top:14px; }\\r\\n  .modal-actions button{ flex:1; padding:10px; border-radius:var(--radius); border:none; font-weight:700; cursor:pointer; }\\r\\n  .modal-actions .confirm{ background:var(--accent); color:#fff; }\\r\\n  .modal-actions .cancel{ background:#e2ddd0; color:var(--ink); }\\r\\n\\r\\n  /* ---- Report view ---- */\\r\\n  #reportView, #historyView{ display:none; background:#fff; }\\r\\n  #reportView.open, #historyView.open{ display:block; position:fixed; inset:0; z-index:55; overflow:auto; }\\r\\n  .history-item{\\r\\n    display:flex; justify-content:space-between; align-items:center; gap:12px; flex-wrap:wrap;\\r\\n    padding:14px 0; border-bottom:1px solid #eee;\\r\\n  }\\r\\n  .history-date{ font-weight:700; font-size:14px; }\\r\\n  .history-meta{ font-size:12px; color:var(--ink-soft); margin-top:2px; }\\r\\n  .history-view-btn{\\r\\n    border:1px solid var(--line); background:var(--panel); padding:7px 14px; border-radius:var(--radius);\\r\\n    cursor:pointer; font-size:12.5px; font-weight:600;\\r\\n  }\\r\\n  .history-view-btn:hover{ border-color:var(--accent); color:var(--accent); }\\r\\n  .report-page{ max-width:760px; margin:0 auto; padding:30px 24px 80px; }\\r\\n  .report-header{ border-bottom:3px solid var(--ink); padding-bottom:14px; margin-bottom:18px; }\\r\\n  .report-header h1{ font-size:22px; margin:0 0 4px; }\\r\\n  .report-header .meta{ font-size:12.5px; color:var(--ink-soft); }\\r\\n  .report-summary{ display:flex; gap:18px; margin:14px 0 22px; font-size:13px; }\\r\\n  .report-cat{ font-size:14px; font-weight:800; margin:22px 0 10px; border-bottom:1px solid var(--line); padding-bottom:6px; }\\r\\n  .report-item{ margin-bottom:14px; padding-bottom:14px; border-bottom:1px solid #eee; }\\r\\n  .report-item .rt-title{ font-weight:700; font-size:14px; }\\r\\n  .report-badge{\\r\\n    display:inline-block; font-size:10.5px; font-weight:700; padding:2px 8px; border-radius:99px; margin-inline-start:8px;\\r\\n    color:#fff; vertical-align:middle;\\r\\n  }\\r\\n  .rb-notstarted{ background:var(--stone); } .rb-inprogress{ background:var(--amber); color:#231c04; } .rb-done{ background:var(--green); }\\r\\n  .report-item .rt-line{ font-size:12.5px; color:var(--ink-soft); margin-top:3px; }\\r\\n  .report-item img{ max-width:260px; max-height:200px; margin-top:8px; border-radius:4px; border:1px solid var(--line); display:block; }\\r\\n  .report-toolbar{\\r\\n    position:sticky; top:0; background:#fff; border-bottom:1px solid var(--line); padding:10px 16px;\\r\\n    display:flex; gap:8px; justify-content:center; z-index:5;\\r\\n  }\\r\\n  .report-toolbar button{ border:1px solid var(--line); background:var(--panel); padding:8px 14px; border-radius:var(--radius); cursor:pointer; font-size:13px; font-weight:600; }\\r\\n  .report-toolbar button.primary{ background:var(--accent); color:#fff; border-color:var(--accent); }\\r\\n  .report-status-section{ margin:26px 0; }\\r\\n  .report-status-heading{\\r\\n    font-size:15px; font-weight:800; margin:0 0 12px; padding-bottom:6px; border-bottom:2px solid var(--line);\\r\\n    display:inline-block; padding-inline-end:10px;\\r\\n  }\\r\\n  .report-status-heading.sh-done{ color:var(--green); border-color:var(--green); }\\r\\n  .report-status-heading.sh-inprogress{ color:#8a6400; border-color:var(--amber); }\\r\\n  .report-status-heading.sh-notstarted{ color:var(--ink-soft); border-color:var(--stone); }\\r\\n  .report-status-empty{ font-size:13px; color:var(--ink-soft); font-style:italic; }\\r\\n  .report-status-item{ font-size:13.5px; line-height:1.7; margin:0 0 14px; }\\r\\n  .report-status-item .rt-cat{ font-size:11.5px; color:var(--ink-soft); }\\r\\n  .report-status-item img{ max-width:260px; max-height:200px; margin-top:6px; border-radius:4px; border:1px solid var(--line); display:block; }\\r\\n  .gantt-legend{ display:flex; gap:16px; font-size:12px; color:var(--ink-soft); margin:10px 0 18px; flex-wrap:wrap; }\\r\\n  .gantt-swatch{ display:inline-block; width:12px; height:12px; border-radius:2px; margin-inline-end:5px; vertical-align:middle; }\\r\\n  .gantt-swatch.gantt-done{ background:var(--green); }\\r\\n  .gantt-swatch.gantt-inprogress{ background:var(--amber); }\\r\\n  .gantt-swatch.gantt-notstarted{ background:var(--stone); }\\r\\n  .gantt-wrap{ display:flex; border:1px solid var(--line); border-radius:4px; overflow:hidden; }\\r\\n  .gantt-labels{ flex:0 0 auto; border-inline-end:1px solid var(--line); background:var(--panel); }\\r\\n  .gantt-label-header{ height:28px; line-height:28px; font-size:11px; font-weight:700; color:var(--ink-soft); padding:0 10px; border-bottom:1px solid var(--line); background:#efe9d8; box-sizing:border-box; }\\r\\n  .gantt-label-row{\\r\\n    height:34px; line-height:34px; padding:0 10px; font-size:12.5px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;\\r\\n    border-bottom:1px solid #eee; box-sizing:border-box;\\r\\n  }\\r\\n  .gantt-scroll{ overflow-x:auto; flex:1 1 auto; }\\r\\n  .gantt-ticks{ position:relative; height:28px; border-bottom:1px solid var(--line); background:#efe9d8; box-sizing:border-box; }\\r\\n  .gantt-tick{ position:absolute; top:0; height:28px; line-height:28px; font-size:10.5px; color:var(--ink-soft); padding-inline-start:4px; border-inline-start:1px solid var(--line); white-space:nowrap; box-sizing:border-box; }\\r\\n  .gantt-rows{ position:relative; background-image:repeating-linear-gradient(to bottom, transparent 0, transparent 33px, #eee 33px, #eee 34px); }\\r\\n  .gantt-bar{\\r\\n    position:absolute; height:22px; border-radius:4px; display:flex; align-items:center; overflow:hidden;\\r\\n    padding:0 6px; box-sizing:border-box;\\r\\n  }\\r\\n  .gantt-bar-label{ font-size:11px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; color:#fff; }\\r\\n  .gantt-bar.gantt-done{ background:var(--green); }\\r\\n  .gantt-bar.gantt-inprogress{ background:var(--amber); }\\r\\n  .gantt-bar.gantt-inprogress .gantt-bar-label{ color:#231c04; }\\r\\n  .gantt-bar.gantt-notstarted{ background:var(--stone); }\\r\\n  @media print{\\r\\n    /* Print only #reportView: display:none (not visibility:hidden) removes\\r\\n       the rest of the app from the layout entirely, so the browser paginates\\r\\n       just the report content instead of reserving space for the whole\\r\\n       on-screen app and effectively \\\"screenshotting\\\" one giant page. */\\r\\n    body > *:not(#reportView){ display:none !important; }\\r\\n    #reportView{ position:static !important; }\\r\\n    .report-toolbar{ display:none !important; }\\r\\n    .report-page{ max-width:none !important; padding:0 !important; }\\r\\n    .report-item, .report-status-item{ break-inside:avoid; page-break-inside:avoid; }\\r\\n    .report-cat, .report-status-heading{ break-after:avoid; page-break-after:avoid; }\\r\\n  }\\r\\n\";\r\nfunction openReport(html,name){if(!/<html[\\s>]/i.test(html))html='<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>'+esc(name)+'</title><style>'+snapshotStyles+' body{padding:24px;background:white}img{max-width:100%}</style></head><body><div id=\"reportContent\">'+html+'</div></body></html>';reportHtml=html;reportName=name;$('#reportTitle').textContent=name;$('#reportFrame').srcdoc=html;$('#reportDialog').showModal()}\r\n$('#downloadReport').onclick=()=>{const blob=new Blob([reportHtml],{type:'text/html'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=reportName.replace(/[^a-z0-9_-]+/gi,'-')+'.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};\r\nwindow.addEventListener('hashchange',()=>{search='';selectedProject='';render()});\r\nwindow.addEventListener('pageshow',event=>{if(event.persisted)load()});\r\nload();\r\n</script><script>// Display-only permissions. Every API operation is independently authorized on the server.\r\nfetch('/api/5s/session').then(async response=>{\r\n if(!response.ok)return;const {user}=await response.json();\r\n const readOnly=['management','site_supervisor'].includes(user.role);\r\n const update=()=>{\r\n  document.querySelectorAll('button[onclick^=\"newProject\"]').forEach(button=>button.hidden=user.role!=='administrator');\r\n  if(!readOnly)return;\r\n  document.querySelectorAll('button[onclick^=\"newVisit\"],button[data-edit-visit],#addBtn,#editSpacesBtn,#selectAllBtn,#deleteSelectedBtn,#importExcelBtn,#renameSpaceBtn,#reportDateBtn,#restoreBtn,#reportBtn,#statusReportBtn,#timelineBtn').forEach(button=>{button.disabled=true;button.style.setProperty('display','none','important')});\r\n  document.querySelectorAll('#main input,#main textarea,#main button').forEach(control=>control.disabled=true);\r\n  document.querySelectorAll('.status-btn,.drag-handle').forEach(control=>control.style.pointerEvents='none');\r\n };\r\n update();const main=document.getElementById('app')||document.getElementById('main');if(main)new MutationObserver(update).observe(main,{subtree:true,childList:true});\r\n}).catch(()=>{});\r\n</script></body></html>\r\n";
